const MAX = 3;
const cache = new Map();
let evicted = 0;
function set(key, val) {
  if (cache.has(key)) cache.delete(key);
  cache.set(key, val);
  if (cache.size > MAX) {
    const oldest = cache.keys().next().value;  // least-recently-used
    cache.delete(oldest);
    evicted++;
  }
}
for (const k of ['a', 'b', 'c', 'd', 'e']) set(k, k.toUpperCase());
console.log('survivors=' + [...cache.keys()].join(',') + ' evicted=' + evicted);

