class Bus {
  constructor(){ this.map = new Map(); } // event -> Set of handlers
  subscribe(event, handler){
    if(!this.map.has(event)) this.map.set(event, new Set());
    const wrapped = (payload) => handler(payload);
    this.map.get(event).add(wrapped);
    return () => { this.map.get(event).delete(handler); };
  }
  listenerCount(event){ return this.map.has(event) ? this.map.get(event).size : 0; }
}

